        q2: ["c-plus-plus", "rust"],
        q3: ["python", "r", "sql"],
      };

      const questionLabels = {
        q1: "Browser languages",
        q2: "Compiled languages",
        q3: "Data analysis languages",
      };

      function getCheckedValues(name) {
        return Array.from(quizForm.querySelectorAll(`input[name="${name}"]:checked`)).map(
          (input) => input.value
        );
      }

      function setQuestionValidity(name, isValid, message) {
        const field = quizForm.querySelector(`.form-field[data-question="${name}"]`);
        const error = document.getElementById(`${name}-error`);
        const inputs = quizForm.querySelectorAll(`input[name="${name}"]`);

        field.classList.toggle("is-invalid", !isValid);
        error.hidden = isValid;
        error.textContent = isValid ? "" : message;

        inputs.forEach((input) => {
          input.setAttribute("aria-invalid", String(!isValid));
          if (isValid) {
            input.removeAttribute("aria-describedby");
          } else {
            const existingIds =
              field.querySelector("fieldset").getAttribute("aria-describedby") || `${name}-error`;
            input.setAttribute("aria-describedby", existingIds);
          }
        });
      }

      function arraysMatch(selected, expected) {
        if (selected.length !== expected.length) {
          return false;
        }

        const selectedSet = new Set(selected);
        return expected.every((item) => selectedSet.has(item));
      }

      function validateSelections() {
        let firstInvalidInput = null;

        Object.keys(answerKey).forEach((questionName) => {
          const selected = getCheckedValues(questionName);
          const isValid = selected.length > 0;

          setQuestionValidity(
            questionName,
            isValid,
            "Choose at least one answer before submitting."
          );

          if (!isValid && !firstInvalidInput) {
            firstInvalidInput = quizForm.querySelector(`input[name="${questionName}"]`);
          }
        });

        return firstInvalidInput;
      }

