          <p>Each question accepts multiple answers, so a question is correct only when every right choice is selected.</p>
          <ul>
            ${details
              .map(
                (detail) =>
                  `<li><strong>${detail.label}:</strong> ${detail.correct ? "Correct" : "Not quite"}</li>`
              )
              .join("")}
          </ul>
