+
+    <script>
+      const quizForm = document.getElementById("quiz-form");
+      const formStatus = document.getElementById("form-status");
+      const results = document.getElementById("results");
+
+      const answerKey = {
+        q1: ["html", "javascript", "css"],
+        q2: ["c-plus-plus", "rust"],
+        q3: ["python", "r", "sql"],
+      };
+
+      const questionLabels = {
+        q1: "Browser languages",
+        q2: "Compiled languages",
+        q3: "Data analysis languages",
+      };
+
+      function getCheckedValues(name) {
+        return Array.from(quizForm.querySelectorAll(`input[name="${name}"]:checked`)).map(
+          (input) => input.value
+        );
+      }
+
+      function setQuestionValidity(name, isValid, message) {
+        const field = quizForm.querySelector(`.form-field[data-question="${name}"]`);
+        const error = document.getElementById(`${name}-error`);
+        const inputs = quizForm.querySelectorAll(`input[name="${name}"]`);
+
+        field.classList.toggle("is-invalid", !isValid);
+        error.hidden = isValid;
+        error.textContent = isValid ? "" : message;
+
+        inputs.forEach((input) => {
+          input.setAttribute("aria-invalid", String(!isValid));
