+              field.querySelector("fieldset").getAttribute("aria-describedby") || `${name}-error`;
+            input.setAttribute("aria-describedby", existingIds);
+          }
+        });
+      }
+
+      function arraysMatch(selected, expected) {
+        if (selected.length !== expected.length) {
+          return false;
+        }
+
+        const selectedSet = new Set(selected);
+        return expected.every((item) => selectedSet.has(item));
+      }
+
+      function validateSelections() {
+        let firstInvalidInput = null;
+
+        Object.keys(answerKey).forEach((questionName) => {
+          const selected = getCheckedValues(questionName);
